function _requireReserveLive() internal view {
    if (!UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().isReserveLive) revert UniswapV4SingleStandardExchangeDETFRepo.ReserveNotLive();
}

function _requireReserveWired() internal view {
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (address(s.bondNftVault) == address(0) || address(s.rebasingClaimToken) == address(0)) {
        revert UniswapV4SingleStandardExchangeDETFRepo.ReserveNotWired();
    }
}

/// @dev Deadline + amount only. Disable is inbound-only (`_requireNotDisabled`).
function _requireActive(uint256 deadline_, uint256 amount_) internal view {
    if (amount_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
    if (block.timestamp > deadline_) revert UniswapV4SingleStandardExchangeDETFRepo.DeadlineExpired(deadline_);
}

function _nftLp() internal view returns (uint256) {
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    address holder_ = _bondLpHolder();
    return IERC20(s.reserveHook).balanceOf(holder_);
}

/// @notice LP on the NFT that is not tracked as user-bonded principal.
function _protocolLp() internal view returns (uint256) {
    uint256 nftLp_ = _nftLp();
    uint256 user_ = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().userBondedLp;
    return nftLp_ > user_ ? nftLp_ - user_ : 0;
}

/// @notice Pull NFT-custodied hook LP onto this diamond before hook withdraw (D13).
function _pullNftLp(uint256 lpAmount_) internal {
    if (lpAmount_ == 0) return;
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    IERC20 lp_ = IERC20(s.reserveHook);
    uint256 have_ = lp_.balanceOf(address(this));
    if (have_ >= lpAmount_) return;
    uint256 need_ = lpAmount_ - have_;
    address holder_ = _bondLpHolder();
    if (holder_ == address(this)) {
        if (have_ < lpAmount_) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();
        return;
    }
    if (need_ > lp_.balanceOf(holder_)) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();
    IDETFNFTVault(holder_).transferHeldToken(lp_, address(this), need_);
}

/// @dev Back-compat name used by burn / claim unwind.
function _pullProtocolLp(uint256 lpAmount_) internal {
    _pullNftLp(lpAmount_);
}

/// @notice Pull LP from bond NFT (maturity close via claimLiquidity).
function _pullBondLp(uint256 lpAmount_) internal {
    _pullNftLp(lpAmount_);
}

function _ensureProtocolLpAvailable(uint256 lpAmount_) internal view {
    if (lpAmount_ > _nftLp()) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();
}

function _isMintingAllowed() internal view returns (bool) {
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (!s.isReserveLive) return false;
    return DETFThresholdPolicy._isMintingAllowed(s.thresholdMode, s.mintThreshold, _syntheticPrice());
}

function _isBurningAllowed() internal view returns (bool) {
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (!s.isReserveLive) return false;
    return DETFThresholdPolicy._isBurningAllowed(s.thresholdMode, s.burnThreshold, _syntheticPrice());
}

function _withdrawSinglePair(uint256 lpAmount_, address to_) internal returns (uint256 pairOut_) {
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    IERC20(s.reserveHook).forceApprove(s.reserveHook, lpAmount_);
    pairOut_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).withdrawSingle(
        lpAmount_, address(s.pairToken), to_, 0, block.timestamp + 1
    );
}

function _pullToken(IERC20 token_, uint256 amount_, bool pretransferred_) internal returns (uint256 actual_) {
    uint256 R = MultiAssetBasicVaultRepo._reserveOfToken(address(token_));
    uint256 B0 = token_.balanceOf(address(this));
    if (!pretransferred_) {
        token_.safeTransferFrom(msg.sender, address(this), amount_);
        return token_.balanceOf(address(this)) - B0;
    }
    uint256 U = B0 - R;
    if (amount_ > U) {
        revert ISecurePullErrors.TransferDeltaInsufficient(amount_, U);
    }
    return amount_;
}

function _burnDetfExactIn(
    uint256 detfIn_,
    IERC20 tokenOut_,
    uint256 minOut_,
    address recipient_,
    bool pretransferred_,
    uint256 /* deadline_ */
) internal returns (uint256 amountOut_) {
    _requireReserveLive();
    _realizeExpansionIfNeeded();
    if (!_isBurningAllowed()) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s0 = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        revert UniswapV4SingleStandardExchangeDETFRepo.BurningNotAllowed(_syntheticPrice(), s0.burnThreshold);
    }
    if (recipient_ == address(0)) recipient_ = msg.sender;

    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (address(tokenOut_) != address(s.pairToken)) {
        revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(this)), tokenOut_);
    }

    uint256 actualIn_ = _pullToken(IERC20(address(this)), detfIn_, pretransferred_);
    uint256 supply_ = ERC20Repo._totalSupply();
    uint256 nftLp_ = _nftLp();
    if (nftLp_ == 0 || supply_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();

    uint256 lpOut_ = actualIn_ * nftLp_ / supply_;
    if (lpOut_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();

    _burnDetf(address(this), actualIn_);
    _ensureProtocolLpOnDiamond(lpOut_);
    amountOut_ = _withdrawSinglePair(lpOut_, recipient_);

    if (amountOut_ < minOut_) {
        revert IStandardExchangeErrors.MinAmountNotMet(minOut_, amountOut_);
    }
    _syncAllExpectedHoldReserves();
}

function _previewBurnDetfExactIn(uint256 detfIn_, IERC20 tokenOut_)
    internal
    view
    returns (uint256 amountOut_)
{
    if (!UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().isReserveLive) return 0;
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (address(tokenOut_) != address(s.pairToken)) return 0;
    if (detfIn_ == 0) return 0;
    uint256 supply_ = ERC20Repo._totalSupply();
    uint256 nftLp_ = _nftLp();
    if (nftLp_ == 0 || supply_ == 0) return 0;
    uint256 lpOut_ = detfIn_ * nftLp_ / supply_;
    if (lpOut_ == 0) return 0;
    amountOut_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).previewWithdrawSingle(lpOut_, address(s.pairToken));
}

function exchangeIn(
    IERC20 tokenIn_,
    uint256 amountIn_,
    IERC20 tokenOut_,
    uint256 minAmountOut_,
    address recipient_,
    bool pretransferred_,
    uint256 deadline_
) public virtual nonReentrant returns (uint256 amountOut_) {
    _requireActive(deadline_, amountIn_);
    if (address(tokenIn_) != address(this)) {
        _requireNotDisabled();
    }
    if (recipient_ == address(0)) recipient_ = msg.sender;

    if (address(tokenIn_) == address(this)) {
        return _burnDetfExactIn(amountIn_, tokenOut_, minAmountOut_, recipient_, pretransferred_, deadline_);
    }
    if (address(tokenOut_) == address(this)) {
        amountOut_ = _mintPath(tokenIn_, amountIn_, recipient_, pretransferred_, deadline_);
        if (amountOut_ < minAmountOut_) {
            revert IStandardExchangeErrors.MinAmountNotMet(minAmountOut_, amountOut_);
        }
        _syncAllExpectedHoldReserves();
        return amountOut_;
    }
    if (address(tokenIn_) != address(this)) {
        amountOut_ =
            _sePassthrough(tokenIn_, amountIn_, tokenOut_, minAmountOut_, recipient_, pretransferred_, deadline_);
        _syncAllExpectedHoldReserves();
        return amountOut_;
    }
    revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(tokenIn_, tokenOut_);

function _spendAllowance(Storage storage layoutStruct, address owner, address spender, uint256 amount) internal {
    if (spender == address(0)) {
        // Revert if address(0).
        revert IERC20Errors.ERC20InvalidSpender(spender);
    }
    uint256 currentAllowance = _allowance(layoutStruct, owner, spender);
    if (currentAllowance < amount) {
        revert IERC20Errors.ERC20InsufficientAllowance(spender, currentAllowance, amount);
    }
    _approve(layoutStruct, owner, spender, currentAllowance - amount);
}

function _transfer(Storage storage layoutStruct, address owner, address recipient, uint256 amount) internal {
    // address(0) MAY NEVER spend it's balance.
    if (msg.sender == address(0)) {
        // Revert if address(0).
        revert IERC20Errors.ERC20InvalidSpender(msg.sender);
    }
    // Decrease the balance of `sender` by `amount`.
    _decreaseBalanceOf(layoutStruct, owner, amount);
    // Increase the balance of `recipient` by `amount`.
    _increaseBalanceOf(layoutStruct, recipient, amount);
    emit IERC20Events.Transfer(owner, recipient, amount);
}

function _transferFrom(Storage storage layoutStruct, address owner, address recipient, uint256 amount) internal {
    // Spend the allowance of `msg.sender` for `owner` by `amount`.
    _spendAllowance(layoutStruct, owner, msg.sender, amount);
    // Transfer the tokens.
    _transfer(layoutStruct, owner, recipient, amount);
}

